INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Credential Stuffing dasselbe wie ein Brute-Force-Angriff?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzt gestohlene Daten, nicht geratene"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Methoden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit diesem Angriff?', 3, '[{"text": "Konten übernehmen", "correct": true, "because": "Nutzt Passwortwiederverwendung"}, {"text": "Server überlasten", "correct": false, "because": "Nicht primär"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Kein Ransomware-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen schützen vor diesem Angriff?', 5, '[{"text": "MFA", "correct": true, "because": "Zweiter Faktor stoppt Bots"}, {"text": "Einmalige Passwörter", "correct": true, "because": "Verhindert Wiederverwendung"}, {"text": "Schnellere Server", "correct": false, "because": "Kein Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es nutzt gestohlene Zugangsdaten. b) Es ist leicht zu erkennen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Erkennung ist schwierig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Abwehr dieses Angriffs?', 4, '[{"text": "Login-Überwachung", "correct": false, "because": "Erkennt Angriffe"}, {"text": "Nutzeraufklärung", "correct": false, "because": "Reduziert Risiko"}, {"text": "Bildschirmgröße", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob dieser Angriff immer Bots nutzt?', 2, '[{"text": "Ja", "correct": true, "because": "Automation ist typisch"}, {"text": "Nein", "correct": false, "because": "Selten manuell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft mir, diesen Angriff zu erkennen?', 3, '[{"text": "Login-Monitoring", "correct": true, "because": "Zeigt Anomalien"}, {"text": "Grafiksoftware", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Texteditor", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen diesen Angriff effektiv?', 5, '[{"text": "Passwortwiederverwendung", "correct": true, "because": "Erhöht Erfolgsquote"}, {"text": "Botnets", "correct": true, "because": "Skaliert Angriffe"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein direkter Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Es nutzt Datenlecks. b) Es ist nur für Banken gefährlich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Branchen betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht zur Abwehr?', 4, '[{"text": "MFA", "correct": false, "because": "Effektivster Schutz"}, {"text": "CAPTCHA", "correct": false, "because": "Erschwert Bots"}, {"text": "Neuer Monitor", "correct": true, "because": "Kein Sicherheitsvorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist dieser Angriff lautlos?', 2, '[{"text": "Nein", "correct": true, "because": "Login-Spitzen sichtbar"}, {"text": "Ja", "correct": false, "because": "Erkennbar bei Überwachung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenquelle nutzt dieser Angriff?', 4, '[{"text": "Datenlecks", "correct": true, "because": "Liefert Zugangsdaten"}, {"text": "Zufallsgenerator", "correct": false, "because": "Brute-Force-spezifisch"}, {"text": "Hardware-Logs", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass starke Passwörter schützen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Wiederverwendung ist das Problem"}, {"text": "Ja", "correct": false, "because": "Stärke allein reicht nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich zur Verhinderung?', 3, '[{"text": "MFA-Einführung", "correct": true, "because": "Blockiert Bots effektiv"}, {"text": "Schnellere Server", "correct": false, "because": "Kein Schutz"}, {"text": "Manuelle Prüfung", "correct": false, "because": "Zu langsam"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es skaliert mit Bots. b) Es ist nur lokal gefährlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Global einsetzbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Branchen sind besonders gefährdet?', 5, '[{"text": "Finanzwesen", "correct": true, "because": "Hoher Wert der Konten"}, {"text": "E-Commerce", "correct": true, "because": "Kundendaten attraktiv"}, {"text": "Gaming", "correct": false, "because": "Weniger primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Abwehr unwichtig?', 3, '[{"text": "Login-Tracking", "correct": false, "because": "Erkennt Angriffe"}, {"text": "Nutzertraining", "correct": false, "because": "Fördert Sicherheit"}, {"text": "CPU-Leistung", "correct": true, "because": "Kein direkter Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt dieser Angriff nur Passwörter?', 3, '[{"text": "Nein", "correct": true, "because": "Auch Benutzernamen nötig"}, {"text": "Ja", "correct": false, "because": "Kombination erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob dieser Angriff selten ist?', 2, '[{"text": "Nein", "correct": true, "because": "Häufig wegen Datenlecks"}, {"text": "Ja", "correct": false, "because": "Sehr verbreitet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik stoppt diesen Angriff am besten?', 4, '[{"text": "Multi-Faktor-Authentifizierung", "correct": true, "because": "Zweiter Faktor fehlt Bots"}, {"text": "IP-Blockierung", "correct": false, "because": "Umgehbar"}, {"text": "Starke Firewalls", "correct": false, "because": "Nicht spezifisch genug"}]');
